<?php
namespace App\Filament\Pages;
use Filament\Pages\Page;
use Illuminate\Support\Facades\DB;
class GraduationDashboard extends Page { protected static ?string $navigationLabel='Выпуск'; protected static ?string $navigationGroup='Учебная часть'; protected static string $view='filament.pages.graduation-dashboard'; public array $rows=[],$stats=[]; public function mount():void { $p=request()->attributes->get('academic_period'); if(!$p)return; $q=DB::table('graduation_records as gr')->join('students as s','s.id','=','gr.student_id')->join('study_groups as g','g.id','=','gr.study_group_id')->where('gr.academic_period_id',$p->id)->select('gr.*','s.last_name','s.first_name','s.middle_name','g.name as group_name')->orderBy('g.name')->orderBy('s.last_name')->get(); $this->rows=$q->map(function($x){$docs=DB::table('graduation_documents')->where('graduation_record_id',$x->id);return (array)$x+['documents'=>$docs->count(),'issued'=>$docs->whereNotNull('received_at')->count()];})->all(); $a=collect($this->rows);$this->stats=['total'=>$a->count(),'ready'=>$a->where('readiness','ready')->count(),'blocked'=>$a->where('readiness','blocked')->count(),'prepared'=>$a->where('status','prepared')->count()]; } public static function canAccess():bool { $u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic')||$u->hasRole('academic_head')); } }
